program = '''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    boxes = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if (all(g[r0][c] == color and g[r1][c] == color for c in range(c0, c1 + 1)) and
            all(g[r][c0] == color and g[r][c1] == color for r in range(r0, r1 + 1))):
            boxes.append((color, r0, r1, c0, c1))
    sources = []
    for color, r0, r1, c0, c1 in boxes:
        interior = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
        if any(g[r][c] == color for r, c in interior):
            sources.append((color, r0, r1, c0, c1))
    if not sources:
        return g
    color, sr0, sr1, sc0, sc1 = sources[0]
    ih, iw = sr1 - sr0 - 1, sc1 - sc0 - 1
    mask = [[g[sr0 + 1 + r][sc0 + 1 + c] == color for c in range(iw)] for r in range(ih)]
    for other, r0, r1, c0, c1 in boxes:
        if (other, r0, r1, c0, c1) == (color, sr0, sr1, sc0, sc1):
            continue
        oh, ow = r1 - r0 - 1, c1 - c0 - 1
        if (oh, ow) != (ih, iw):
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    g[r][c] = 0
        else:
            for r in range(ih):
                for c in range(iw):
                    if mask[r][c]:
                        g[r0 + 1 + r][c0 + 1 + c] = other
    return g
'''
